INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (1, 2, 3, 'Pessoal do 3º DS: a entrega parcial do TCC foi adiada para o dia 28. Aproveitem para revisar a documentação e o diagrama de casos de uso. Qualquer dúvida, me chamem aqui ou nas mensagens!', '2026-11-13 17:00:00');
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (2, 8, 3, 'Que orgulho da turma de Design Gráfico! Os cartazes da Semana da Consciência Negra ficaram incríveis e já estão expostos no corredor do bloco B. 🎨', '2026-11-13 13:00:00');
INSERT INTO post_media (post_id, media_url, media_type, media_order) VALUES (2, 'uploads/mediaPost/seed/post1.jpg', 'image', 0);
INSERT INTO post_media (post_id, media_url, media_type, media_order) VALUES (2, 'uploads/mediaPost/seed/post2.jpg', 'image', 1);
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (3, 2, 3, 'Lembrete: amanhã teremos aula prática de banco de dados no laboratório 4. Tragam o script DDL do projeto de vocês, vamos normalizar juntos.', '2026-11-13 00:00:00');
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (4, 8, 3, 'Abertas as inscrições para a oficina de UI/UX no sábado. Vagas limitadas! Inscrevam-se pela aba Eventos.', '2026-11-12 14:00:00');
INSERT INTO post_media (post_id, media_url, media_type, media_order) VALUES (4, 'uploads/mediaPost/seed/post3.jpg', 'image', 0);
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (5, 2, 3, 'Parabéns ao grupo do EteConnect pela apresentação na banca prévia. Projeto muito bem estruturado, com front, API e banco funcionando de ponta a ponta. 👏', '2026-11-11 16:00:00');
INSERT INTO post_media (post_id, media_url, media_type, media_order) VALUES (5, 'uploads/mediaPost/seed/post4.jpg', 'image', 0);
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (6, 8, 3, 'Biblioteca recebeu novos livros de tipografia e design de interfaces. Corram para reservar!', '2026-11-10 17:00:00');
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (7, 2, 3, 'Material da aula de hoje sobre JWT e refresh tokens já está disponível. Revisem a diferença entre autenticação e autorização antes da prova.', '2026-11-09 18:00:00');
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (8, 8, 3, 'Visita técnica à agência de design confirmada para o dia 05/12. Levem a autorização assinada pelos responsáveis.', '2026-11-08 10:00:00');
INSERT INTO post_media (post_id, media_url, media_type, media_order) VALUES (8, 'uploads/mediaPost/seed/post5.jpg', 'image', 0);
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (9, 13, 29, 'Bem-vindos ao servidor da Etec Parque da Juventude! Usem este espaço para dúvidas sobre as disciplinas de programação.', '2026-11-13 10:00:00');
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (10, 16, 29, 'Hackathon interno confirmado: 48h, temas ligados a sustentabilidade. Montem seus grupos de até 4 pessoas!', '2026-11-12 04:00:00');
INSERT INTO post_media (post_id, media_url, media_type, media_order) VALUES (10, 'uploads/mediaPost/seed/post6.jpg', 'image', 0);
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (11, 13, 29, 'Resultados do simulado de lógica de programação já foram lançados. Média da turma: 7,8. Mandaram bem!', '2026-11-10 02:00:00');
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (12, 2, 1, 'Olá a todas as Etecs! Este é o servidor geral do ETEConnect — compartilhem eventos abertos, oportunidades de estágio e projetos.', '2026-11-13 15:00:00');
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (13, 16, 1, 'Feira de Profissões do Centro Paula Souza acontece mês que vem. Ótima oportunidade para quem está decidindo a graduação.', '2026-11-12 18:00:00');
INSERT INTO post_media (post_id, media_url, media_type, media_order) VALUES (13, 'uploads/mediaPost/seed/post2.jpg', 'image', 0);
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (14, 8, 1, 'Dica de estudo: o Figma tem plano gratuito para estudantes. Vale muito a pena para prototipar o front do TCC.', '2026-11-11 08:00:00');
INSERT INTO post (id, id_author, server_id, content, created_at) VALUES (15, 13, 1, 'Vagas de estágio em desenvolvimento web na zona leste — mandem o currículo para o e-mail da coordenação.', '2026-11-09 06:00:00');
INSERT INTO comment (id, id_post, id_author, id_parent_comment, content, created_at) VALUES (1, 1, 1, NULL, 'Ufa! Professor, a documentação pode ser entregue em PDF?', '2026-11-13 17:30:00');
INSERT INTO comment (id, id_post, id_author, id_parent_comment, content, created_at) VALUES (2, 1, 2, 1, 'Pode sim, Ana. Só não esqueçam a capa padrão da Etec.', '2026-11-13 17:48:00');
INSERT INTO comment (id, id_post, id_author, id_parent_comment, content, created_at) VALUES (3, 1, 3, NULL, 'Valeu prof, vai dar tempo de terminar o diagrama de classes.', '2026-11-13 18:00:00');
INSERT INTO comment (id, id_post, id_author, id_parent_comment, content, created_at) VALUES (4, 2, 4, NULL, 'Obrigada professora!! Foi muito trabalho mas valeu a pena 💛', '2026-11-13 14:00:00');
INSERT INTO comment (id, id_post, id_author, id_parent_comment, content, created_at) VALUES (5, 2, 15, 4, 'Ficou top demais o seu, Mari!', '2026-11-13 14:30:00');
