INSERT INTO comment (id, id_post, id_author, id_parent_comment, content, created_at) VALUES (8, 5, 1, NULL, 'Obrigada professor! O grupo todo agradece 🙌', '2026-11-11 18:00:00');
INSERT INTO comment (id, id_post, id_author, id_parent_comment, content, created_at) VALUES (9, 5, 9, NULL, 'Arrasaram demais!', '2026-11-11 19:00:00');
