INSERT INTO comment (id, id_post, id_author, id_parent_comment, content, created_at) VALUES (11, 4, 5, NULL, 'Já me inscrevi! Vai ter certificado?', '2026-11-12 16:00:00');
INSERT INTO comment (id, id_post, id_author, id_parent_comment, content, created_at) VALUES (12, 4, 8, 11, 'Vai sim, Gabriel. 4 horas complementares.', '2026-11-12 17:00:00');
INSERT INTO comment (id, id_post, id_author, id_parent_comment, content, created_at) VALUES (13, 9, 11, NULL, 'Professor, as listas de exercícios vão ficar aqui também?', '2026-11-13 11:00:00');
INSERT INTO comment (id, id_post, id_author, id_parent_comment, content, created_at) VALUES (14, 10, 12, NULL, 'Já temos grupo formado! Bora 🚀', '2026-11-12 06:00:00');
INSERT INTO comment (id, id_post, id_author, id_parent_comment, content, created_at) VALUES (15, 12, 3, NULL, 'Que legal ter um espaço com todas as Etecs!', '2026-11-13 16:00:00');
