INSERT INTO message (sender_id, receiver_id, content, created_at, is_read) VALUES (3, 1, 'Funcionou 🔥', '2026-11-13 19:30:00', FALSE);
INSERT INTO message (sender_id, receiver_id, content, created_at, is_read) VALUES (4, 1, 'Fiz uns mockups novos pro feed, quer ver?', '2026-11-12 14:00:00', TRUE);
INSERT INTO message (sender_id, receiver_id, content, created_at, is_read) VALUES (1, 4, 'Quero muito! Me manda', '2026-11-12 15:00:00', TRUE);
INSERT INTO message (sender_id, receiver_id, content, created_at, is_read) VALUES (4, 1, 'Te mando amanhã no intervalo', '2026-11-13 17:00:00', FALSE);
